43: function gc(seq){return seq?((seq.match(/[GC]/g)||[]).length/seq.length*100):0}
44: function genomeSequence(g){let s='';for(const gene of g.genes){s+=gene.promoter+gene.enhancer+gene.coding.slice(0,Math.floor(gene.coding.length/2))+gene.intron+gene.coding.slice(Math.floor(gene.coding.length/2))}return s+g.noncoding}
