46: function traitMap(g,env){let map={},stress=environmentStress(env);for(const gene of g.genes){let envFactor=1;if(gene.regulation==='stress-inducible')envFactor=clamp(.24+stress*.95,.18,1);if(gene.regulation==='nutrient-responsive')envFactor=clamp(.22+env.nutrients*.9,.2,1);if(gene.regulation==='developmental')envFactor=.45+Math.sin(g.generation*.11)*.2;map[gene.name]=clamp(gene.activity*envFactor*(1-gene.epi)*(gene.mutation?.8:1),.02,1)}return map}
47: function expressionProfile(g,env){const exp=traitMap(g,env);return g.genes.map(x=>({...x,expression:exp[x.name],protein:translate(transcribe(x))}))}
48: function makePlateState(genome,seed,viability,atp,count=12,archived=false){let rng=new RNG(hashSeed(`${seed}:plate`)),source=JSON.parse(JSON.stringify(genome)),cells=[];for(let i=0;i<count;i++)cells.push({id:`CELL-${String(i+1).padStart(3,'0')}`,genomeId:genome.id,parentGenomeId:genome.origin||null,viability:clamp(viability+rng.normal()*2.2,35,100),atp:clamp(atp+rng.normal()*.12,.2,7),damage:clamp((100-viability)*.08+rng.next()*2,0,100),ros:clamp(rng.next()*8,0,100),membrane:clamp(96+rng.normal()*1.5,0,100),proteinLoad:clamp(rng.next()*8,0,100),state:'cycling',generation:genome.generation||0,mutationCount:genome.mutations||0,mutationDetails:[],archived,sourceLabel:archived?'ARCHIVE':'LIVE CULTURE',x:12+rng.next()*76,y:14+rng.next()*72,phase:rng.next()*6.28,cycleProgress:rng.next()*.72,age:0,divisions:0,stained:false});return{plate:cells,plateSources:{[genome.id]:source},plateSequence:count,selectedCellId:cells[0]?.id||null}}
49: function initialState(seed,source){let rng=new RNG(hashSeed(seed)),genome=makeGenome(seed,source),env={temperature:20+rng.next()*12,radiation:rng.next()*.18,nutrients:.45+rng.next()*.5,oxygen:.42+rng.next()*.55,water:.45+rng.next()*.5,ph:6.4+rng.next()*1.8,chemical:0};genome.sequence=genomeSequence(genome);let exp=traitMap(genome,env),fitness=clamp(.62+Object.values(exp).reduce((a,b)=>a+b,0)/Object.keys(exp).length*.2-rng.next()*.12,.3,.95);return{seed,genome,env,tick:0,generation:0,population:120+rng.int(280),fitness,viability:91+rng.next()*8,atp:2.1+rng.next()*1.3,damage:rng.next()*7,senescence:rng.next()*4,diversity:.08+rng.next()*.12,history:[],events:[{tick:0,type:'origin',text:'A viable population establishes in the tidal microhabitat.'}],samples:{dna:false,rna:false},labResults:[],notebook:[],archive:[],speed:1,playing:false,selectedGene:0,cellCount:2400+rng.int(700),liveCells:0,sourceId:source?.id||null,experimentCount:0,researchXP:0,researchLevel:1,...makePlateState(genome,seed,91,2.7)}}
