53: if(!Array.isArray(S.plate)){Object.assign(S,makePlateState(S.genome,S.seed,S.viability||90,S.atp||2.5))}S.plateSources=S.plateSources||{[S.genome.id]:JSON.parse(JSON.stringify(S.genome))};S.plateSequence=S.plateSequence||S.plate.length;for(const c of S.plate){c.damage=c.damage??Math.max(0,100-c.viability)*.08;c.cycleProgress=c.cycleProgress??0;c.age=c.age??0;c.divisions=c.divisions??0;c.parentGenomeId=c.parentGenomeId??null;c.lineageOrigin=c.lineageOrigin??c.parentGenomeId;c.generation=c.generation??(S.plateSources?.[c.genomeId]?.generation||0);c.mutationCount=c.mutationCount??(S.plateSources?.[c.genomeId]?.mutations||0);c.mutationDetails=Array.isArray(c.mutationDetails)?c.mutationDetails:[];c.stained=c.stained??false;c.ros=c.ros??0;c.membrane=c.membrane??clamp(100-(c.damage||0)*.35,0,100);c.proteinLoad=c.proteinLoad??0;c.state=c.state||'cycling';c.stainIntensity=c.stainIntensity??null;c.elementExposures=c.elementExposures&&typeof c.elementExposures==='object'&&!Array.isArray(c.elementExposures)?c.elementExposures:{}}S.selectedCellId=S.selectedCellId||S.plate[0]?.id||null;S.selectedElement=ELEMENTS.some(e=>e.symbol===S.selectedElement)?S.selectedElement:'C';S.researchXP=Number.isFinite(S.researchXP)?Math.max(0,S.researchXP):0;S.researchSuccesses=Math.max(0,Number(S.researchSuccesses)||0);S.researchLevel=Number.isSafeInteger(S.researchLevel)&&S.researchLevel>=1?S.researchLevel:1;while(S.researchXP>=S.researchLevel*100&&Number.isFinite(S.researchLevel))S.researchXP-=S.researchLevel++*100;
