55: function recordResearchSuccess(label){S.researchSuccesses=(S.researchSuccesses||0)+1;S.researchXP=(S.researchXP||0)+100;let oldLevel=S.researchLevel||1;while(S.researchXP>=S.researchLevel*100)S.researchXP-=S.researchLevel++*100;return{level:S.researchLevel,leveled:S.researchLevel>oldLevel,label}}
