133: function sequenceSimilarity(a,b){
  if(!b)return 1;
  let n=Math.min(a.length,b.length),same=0;
  for(let i=0;
  i<n;
  i++)if(a[i]===b[i])same++;
  return same/Math.max(a.length,b.length)}
