function geneRows(){let genome=S.inspectedGenome||S.genome;return genome.genes.map((g,i)=>`<div class="gene-row" data-gene="${i}"><span class="gene-id">${g.id} ${g.mutation?'⚠':''}</span><span class="gene-function">${g.name}<small>${g.regulation.toUpperCase()} · chr ${g.chromosome}</small></span><div class="expression-bar"><i style="width:${Math.round(traitMap(genome,S.env)[g.name]*100)}%"></i></div><span class="gene-value">${f(traitMap(genome,S.env)[g.name],2)}×</span></div>`).join('')}
function plateGenome(cell){return S.plateSources?.[cell.genomeId]||S.archive?.find(g=>g.id===cell.genomeId)|| (S.genome.id===cell.genomeId?S.genome:S.genome)}
function plateCellMarkup(cell){let genome=plateGenome(cell),traits=traitMap(genome,S.env),energy=traits['ATP synthase']||.5,light=traits['Photoreceptor']||.35,hue=Math.round(145+light*65),speed=(3.8-energy*2.1).toFixed(2),selected=cell.id===S.selectedCellId,exposureCount=Object.values(cell.elementExposures||{}).reduce((sum,count)=>sum+count,0);return `<button class="plate-cell ${selected?'selected':''} ${cell.archived?'archived':''} ${cell.viability<55?'stressed':''} ${cell.stained?'stained':''} ${exposureCount?'element-exposed':''}" data-plate-cell="${cell.id}" aria-label="Select ${cell.id}, ${cell.archived?'archived':'live'} cell from ${cell.genomeId}; viability ${f(cell.viability,0)} percent${exposureCount?`; ${exposureCount} sandbox element markers`:''}" title="${cell.id} · ${cell.genomeId} · ${f(cell.viability,0)}% viable · ${cell.state||'cycling'} · ${cycleStage(cell.cycleProgress||0)} / ${cycleCheckpoint(cell)}${exposureCount?` · ${exposureCount} sandbox markers`:''}" style="left:${cell.x}%;top:${cell.y}%;--cell-hue:${hue};--cell-speed:${speed}s;--cell-glow:${(0.25+energy*.55).toFixed(2)};--cell-size:${(24+energy*9).toFixed(1)}px;--cell-damage:${Math.round(cell.damage||0)}%;--stain-intensity:${Math.round(cell.stainIntensity??cell.viability)}"><span class="plate-cell-body"><i class="plate-nucleus"></i><i class="plate-organelle p1"></i><i class="plate-organelle p2"></i><i class="plate-organelle p3"></i></span><span class="plate-cell-id">${cell.id.slice(-3)}${exposureCount?` · ${exposureCount}×`:''}</span></button>`}
function addCellsToPlate(genome,archived=false,count=6){S.plate=S.plate||[];let free=30-S.plate.length;if(free<=0){toast('Observatory plate is full · remove cells before adding more.');return[]}count=Math.min(count,free);S.plateSources=S.plateSources||{};S.plateSources[genome.id]=JSON.parse(JSON.stringify(genome));let rng=new RNG(hashSeed(`${S.seed}:${genome.id}:${S.plateSequence}:plate-add`)),mean=Object.values(traitMap(genome,S.env)).reduce((a,b)=>a+b,0)/genome.genes.length;let added=[];for(let i=0;i<count;i++){let n=++S.plateSequence,cell={id:`CELL-${String(n).padStart(3,'0')}`,genomeId:genome.id,viability:clamp((archived?74+mean*23:S.viability)+rng.normal()*2,35,100),atp:clamp((archived?1.1+(traitMap(genome,S.env)['ATP synthase']||.5)*3:S.atp)+rng.normal()*.13,.2,7),damage:clamp(rng.next()*4,0,100),ros:clamp(rng.next()*5,0,100),membrane:clamp(97+rng.normal(),0,100),proteinLoad:clamp(rng.next()*5,0,100),state:'cycling',generation:genome.generation||0,archived,sourceLabel:archived?'ARCHIVE':'LIVE CULTURE',x:10+rng.next()*80,y:12+rng.next()*76,phase:rng.next()*6.28,cycleProgress:rng.next()*.3,age:0,divisions:0,stained:false};S.plate.push(cell);added.push(cell)}S.selectedCellId=added[0]?.id||S.selectedCellId;storeState();return added}
function periodicTableMarkup(){let selected=S.selectedElement||'C',rows=PERIODIC_ROWS.slice(0,7).map(row=>row.map(item=>{let symbol=item.split(':')[0],element=ELEMENTS.find(e=>e.symbol===symbol);return element?`<button class="element-tile ${selected===symbol?'selected':''}" data-element="${symbol}" aria-pressed="${selected===symbol}" aria-label="${element.number} ${element.name}" title="${element.number} · ${element.name}" style="grid-row:${ELEMENT_POSITIONS[symbol][0]};grid-column:${ELEMENT_POSITIONS[symbol][1]}"><small>${element.number}</small><strong>${symbol}</strong></button>`:''}).join('')).join('');let fBlock=(prefix)=>ELEMENTS.filter(e=>e.symbol in ELEMENT_POSITIONS&&ELEMENT_POSITIONS[e.symbol][0]===(prefix==='La'?8:9)).map(e=>`<button class="element-tile ${selected===e.symbol?'selected':''}" data-element="${e.symbol}" aria-pressed="${selected===e.symbol}" aria-label="${e.number} ${e.name}" title="${e.number} · ${e.name}"><small>${e.number}</small><strong>${e.symbol}</strong></button>`).join('');return `<div class="periodic-scroll"><div class="periodic-grid">${rows}</div><div class="periodic-f-block"><span>Lanthanides</span><div>${fBlock('La')}</div><span>Actinides</span><div>${fBlock('Ac')}</div></div></div>`}
function elementResultMarkup(){let element=ELEMENTS.find(e=>e.symbol===S.selectedElement)||ELEMENTS.find(e=>e.symbol==='C'),guide=ELEMENT_GUIDE[element.symbol],detail=guide||{title:`${element.name} · periodic-table reference`,badge:'GENERAL ELEMENT CONTEXT',description:`${element.name} (symbol ${element.symbol}, atomic number ${element.number}) is shown here as an educational periodic-table reference. GENESIS does not model this element’s chemistry, biological availability, reactions, or effects on the selected cell.`,source:ELEMENT_REFERENCE.source,url:ELEMENT_REFERENCE.url},cell=S.plate.find(c=>c.id===S.selectedCellId)||S.plate[0],count=cell?.elementExposures?.[element.symbol]||0,total=Object.values(cell?.elementExposures||{}).reduce((sum,n)=>sum+n,0);return `<div class="element-result"><div class="element-result-symbol"><small>ATOMIC NO. ${element.number}</small><strong>${element.symbol}</strong><span>${element.name}</span></div><div class="element-result-copy"><div class="element-result-top"><h3>${detail.title}</h3><span class="tag cyan">${detail.badge}</span></div><p>${detail.description}</p><a href="${detail.url}" target="_blank" rel="noopener noreferrer">Source: ${detail.source} ↗</a><div class="element-plate-response"><div><strong>Selected cell · ${cell?.id||'none'}</strong><span>${count} ${element.symbol} marker${count===1?'':'s'} · ${total} total sandbox marker${total===1?'':'s'}</span></div><button class="subtle-button" data-action="add-element-plate" ${cell?'':'disabled'}>＋ Add ${element.symbol} to plate</button></div><p class="element-response-note">Adds a persistent, visual-only exposure marker to this cell. The marker triggers a brief halo; it does not represent a dose, chemical reaction, or biological effect, and does not alter cell metrics.</p></div></div>`}
function cellView(){if(!S.plate?.length)Object.assign(S,makePlateState(S.genome,S.seed,S.viability,S.atp,0));let selected=S.plate.find(c=>c.id===S.selectedCellId)||S.plate[0],genome=plateGenome(selected),traits=traitMap(genome,S.env),atpExpression=traits['ATP synthase']||.5,stage=cycleStage(selected.cycleProgress||0),checkpoint=cycleCheckpoint(selected),organelles=[['Cell membrane',`${f(selected.membrane,1)}% integrity · transport boundary`],['Cytoplasm',`${f(atpExpression*100,0)}% metabolic activity`],['Nucleus',`${genome.genes.length} annotated loci · ${genome.id}`],['Mitochondria',`${f(selected.atp,2)} mmol/L ATP proxy · ROS ${f(selected.ros,1)}`],['Ribosomes',`${genome.genes.length} active transcript targets`],['Endoplasmic reticulum',`${f((traits['Heat-shock protein']||.5)*100,0)}% folding response · load ${f(selected.proteinLoad,1)}%`],['Golgi apparatus','Protein processing'],['Lysosomes','Turnover · autophagy proxy'],['Cytoskeleton',`${selected.archived?'archived':'live'} lineage · generation ${selected.generation}`],['Cell receptors',`${f((S.env.nutrients+.2)*7,1)} relative signal capacity`]];return `${pageHead(`LIVE IMAGING · CELL ${String(S.tick%9999).padStart(4,'0')}`,'Cell observatory','Every pulse reflects the selected cell’s genome and measured state.',`<button class="subtle-button" data-action="plate-live">＋ Add live cells</button><button class="subtle-button" data-action="cell-cycle">↻ Advance cell cycle</button><button class="subtle-button" data-action="stain">◉ Stain selected</button>`)}<section class="card plate-card"><div class="card-head"><div><span class="card-title">Observatory plate <span class="card-meta">/ CULTURE DISH · ${S.plate.length} OF 30 CELLS</span></span><div class="plate-caption">Select any cell to inspect it. Pulse rate and hue are derived from its expressed genome.</div></div><span class="tag green">${S.plate.length} ON PLATE</span></div><div class="plate-stage"><div class="plate-dish"><div class="plate-rim"></div><div class="plate-well"></div>${S.plate.map(plateCellMarkup).join('')}<span class="plate-crosshair h"></span><span class="plate-crosshair v"></span></div><div class="plate-overlay"><span>FIELD 01</span><span>${S.playing?'MOTION ACTIVE':'MOTION CONTINUES'}</span></div></div><div class="plate-summary"><span>MEAN VIABILITY <b>${f(S.plate.reduce((n,c)=>n+c.viability,0)/S.plate.length,1)}%</b></span><span>STAINED <b>${S.plate.filter(c=>c.stained).length}</b></span><span>MEAN DAMAGE <b>${f(S.plate.reduce((n,c)=>n+(c.damage||0),0)/S.plate.length,1)}%</b></span><span>MEAN ROS <b>${f(S.plate.reduce((n,c)=>n+(c.ros||0),0)/S.plate.length,1)}%</b></span><span>CHECKPOINT BLOCKED <b>${S.plate.filter(c=>cycleCheckpoint(c)!=='PASS').length}</b></span><span>CAPACITY <b>${30-S.plate.length} OPEN</b></span></div><div class="plate-footer"><div class="plate-legend"><span><i class="plate-legend-dot"></i>LIVE CULTURE</span><span><i class="plate-legend-dot archive"></i>ARCHIVED LINEAGE</span><span><i class="plate-legend-dot selected"></i>SELECTED</span></div><div class="plate-load"><select id="plate-archive" aria-label="Choose archived cell"><option value="">Load archived cell…</option>${(S.archive||[]).map((g,i)=>`<option value="${i}">${g.id} · generation ${g.generation}</option>`).join('')}</select><button class="tiny-control" data-action="plate-archive">LOAD TO PLATE</button></div></div></section><div class="cell-layout plate-details"><section class="card"><div class="card-head"><span class="card-title">Selected cell · ${selected.id}</span><span class="tag ${selected.archived?'':'green'}">${selected.sourceLabel}</span></div><div class="selected-lineage"><strong>${genome.id}</strong><span>${genome.species||'Pelagomyces isolate'} · generation ${selected.generation}</span></div><div class="cell-reading"><span>VIABILITY</span><b>${f(selected.viability,1)} %</b></div><div class="cell-reading"><span>ATP · MODEL PROXY</span><b>${f(selected.atp,2)} mmol/L</b></div><div class="cell-reading"><span>DAMAGE · MOD